import{z as d,x as i,o as n,c as A,q as r,j as t,D as e,d as l,s,S as B,b as o}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Reed–Solomon","description":"","frontmatter":{"title":"Reed–Solomon","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/reed-solomon.md","filePath":"cs/reed-solomon.md","lastUpdated":1791413859000}'),m={name:"cs/reed-solomon.md"};function p(S,a,k,C,D,h){const E=i("Mermaid");return n(),A("div",null,[a[2]||(a[2]=r('<h1 id="reed–solomon" tabindex="-1">Reed–Solomon <a class="header-anchor" href="#reed–solomon" aria-label="Permalink to &quot;Reed–Solomon&quot;">​</a></h1><div class="epigraph"><p>把信息当成多项式系数，在有限域的 $n$ 个点上求值；任意 $k$ 个点都能重建，于是可纠 $n-k$ 个符号级擦除，或约一半替换错误。</p><footer>—— 据 Reed and Solomon, 1960；MacWilliams and Sloane 整理</footer></div><p>上一课<a href="/cs/hamming-code">汉明码</a> 是二元、纠 1 比特。缺口是<strong>符号级</strong>：磁盘扇区、QR、光盘上的突发错误。Reed–Solomon（RS）在 \\(\\mathbb{F}_q\\) 上，\\(q\\gt n\\)，码字是次数 \\(\\lt k\\) 的多项式的求值向量。\\(d_{\\min}=n-k+1\\)（Singleton 达到，MDS）。本课要求值图像；有限域构造在数论单元。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>信息 \\(m(x)=m_0+\\cdots+m_{k-1}x^{k-1}\\)。码字 \\((m(\\alpha_1),\\ldots,m(\\alpha_n))\\)。擦除 \\(e\\) 个位置：剩 \\(n-e\\ge k\\) 个点，插值唯一。替换错误 \\(t\\)：Berlekamp–Welch / 关键方程，可纠 \\(t\\le\\lfloor(n-k)/2\\rfloor\\)。突发：二元突发变成少数符号错，RS 比 Hamming 合适。</p><p>不要在本课展开 \\(\\mathrm{GF}(2^8)\\) 的不可约多项式——只假设能算加减乘除。</p><h3 id="距离是符号汉明距离" tabindex="-1">距离是符号汉明距离 <a class="header-anchor" href="#距离是符号汉明距离" aria-label="Permalink to &quot;距离是符号汉明距离&quot;">​</a></h3><p><a href="/cs/hamming-distance">汉明距离</a> 课已声明 RS 换字母表。一个符号错可以是 8 比特全翻，仍只计距离 1。</p><p><span class="marginnote">Reed–Solomon 1960。Peterson、Berlekamp 译码。Justesen、Guruswami–Sudan 列表译码点名。存储阵列、QR 是应用，不是定义。</span></p><p><span class="marginnote">直觉类比：两点定一条直线、三点定一条抛物线——\\(k\\) 个系数的多项式由任意 \\(k\\) 个点唯一确定。RS 把消息藏进多项式，只要丢失后还剩 \\(k\\) 个点，就能把整条曲线描回来，缺的符号再代值重算。</span></p><p><span class="marginnote">数字实例：\\(k=2,n=4\\) 时 \\(d=n-k+1=3\\)，能纠 2 个擦除（\\(n-k\\)），或 1 个替换错误（\\(\\lfloor(n-k)/2\\rfloor\\)）。QR 码常用的 \\(\\mathrm{GF}(2^8)\\) 一个符号 8 比特：整字节被划花也只算 1 个符号错，这正是 RS 对付突发错误的本钱。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用小域手写 \\(k=2,n=4\\) 求值。对照重复码、Hamming：MDS 在给定 \\(n,k\\) 下 \\(d\\) 最大。指出：编码是线性的（Vandermonde）。译码比伴随式定位重，本课只给「插值 / 关键方程」名字。</p>',13)),(n(),t(B,null,{default:e(()=>[s(E,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20MSG%5B%22k%20%E4%B8%AA%E7%B3%BB%E6%95%B0%22%5D%20--%3E%20POLY%5B%22%E6%AC%A1%E6%95%B0%20%EF%BC%9C%20k%20%E7%9A%84%E5%A4%9A%E9%A1%B9%E5%BC%8F%22%5D%0A%20%20POLY%20--%3E%20EVAL%5B%22n%20%E4%B8%AA%E7%82%B9%E6%B1%82%E5%80%BC%22%5D%0A%20%20EVAL%20--%3E%20MDS%5B%22d%20%3D%20n-k%2B1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[l("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"容量：RS 不随 \\(n\\to\\infty\\) 在 BSC 上自动达容量（字母表也在涨）。它是代数码的代表，后课 LDPC 才是近容量的稀疏随机码。RS 常作外码，与内码级联。",-1)),a[5]||(a[5]=o("p",null,"多项式观点与主干 CRC 同族：CRC 检错，RS 纠错并给距离公式。",-1)),(n(),t(B,null,{default:e(()=>[s(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20RX%5B%22%E6%94%B6%E5%88%B0%20n%20%E4%B8%AA%E7%AC%A6%E5%8F%B7%22%5D%20--%3E%20KNOWN%7B%22%E5%9D%8F%E4%BD%8D%E7%BD%AE%E5%B7%B2%E7%9F%A5%E5%90%97%3F%22%7D%0A%20%20KNOWN%20--%3E%7C%22%E6%98%AF%EF%BC%9A%E6%93%A6%E9%99%A4%22%7C%20ERA%5B%22%E5%89%A9%20n-e%20%E2%89%A5%20k%20%E4%B8%AA%E5%A5%BD%E7%82%B9%EF%BC%8C%E7%9B%B4%E6%8E%A5%E6%8F%92%E5%80%BC%22%5D%0A%20%20KNOWN%20--%3E%7C%22%E5%90%A6%EF%BC%9A%E6%9B%BF%E6%8D%A2%22%7C%20ERR%5B%22%E4%BD%8D%E7%BD%AE%E6%9C%AA%E7%9F%A5%EF%BC%9A%E5%85%88%E5%AE%9A%E4%BD%8D%E5%86%8D%E6%B1%82%E5%80%BC%22%5D%0A%20%20ERR%20--%3E%20HALF%5B%22%E6%AF%8F%E4%B8%AA%E9%94%99%E5%90%83%202%20%E4%BB%BD%E8%87%AA%E7%94%B1%E5%BA%A6%EF%BC%9At%20%E2%89%A4%20(n-k)%2F2%22%5D%0A%20%20ERA%20--%3E%20RECON%5B%22%E4%BB%BB%E5%8F%96%20k%20%E4%B8%AA%E7%82%B9%E9%87%8D%E5%BB%BA%E5%A4%9A%E9%A1%B9%E5%BC%8F%22%5D%0A%20%20HALF%20--%3E%20RECON%0A%20%20RECON%20--%3E%20BACK%5B%22%E4%BB%A3%E5%9B%9E%E7%BC%BA%E5%A4%B1%E7%82%B9%E8%A1%A5%E5%85%A8%E7%A0%81%E5%AD%97%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>BCH 码把 RS 看成设计距离的子域子码；二进制 BCH 纠少量比特时比 Hamming 更灵活。Guruswami–Sudan 列表译码可超过半距离，代价是列表。级联：外 RS 去突发，内卷积或 LDPC 去随机，是深空通信的经典分层，后课内码。</p><p><span class="marginnote">常见误区：初学者容易觉得「纠 1 个替换错误」与「纠 2 个擦除」两种说法矛盾。其实一致：替换错误的<strong>位置</strong>也得猜，每定位一个错就额外花一份自由度，同样 \\(n-k\\) 的余量拿来纠替换就只剩一半。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Berlekamp–Massey 全文，不引入 BCH 的设计距离。有限域下一单元才系统讲。后课默认：符号 MDS 码即 RS 直觉。下一课卷积与 Viterbi。</p><p>MDS 在给定 \\(n,k\\) 下距离最大，字母表必须够大。插值重建擦除；替换错误要关键方程。有限域算术本单元只假设能做，构造在数论课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RS = 多项式求值；MDS，\\(d=n-k+1\\)。</li><li>纠擦除到 \\(n-k\\)，纠替换到 \\(\\lfloor(n-k)/2\\rfloor\\)。</li><li>字母表是有限域符号，不是比特汉明。</li><li>出处：Reed and Solomon, 1960；MacWilliams and Sloane。</li></ul>',7))])}const u=d(m,[["render",p]]);export{c as __pageData,u as default};
